import math

def calculate_E(n):
    # Expression is E(n) = 3 * ((n+2)! + 1) / (2n - 1)
    try:
        # Calculate (n+2)!
        factorial_term = math.factorial(n + 2)

        # Calculate the numerator N = 3 * ((n+2)! + 1)
        numerator = 3 * (factorial_term + 1)

        # Calculate the denominator D = 2n - 1
        denominator = 2 * n - 1

        if denominator == 0:
            return None # Should not happen for integer n

        # Check for integer result
        if numerator % denominator == 0:
            return numerator // denominator
        else:
            return None
    except ValueError:
        # Handles cases where n+2 might be too large, though unlikely for n<=20
        return None

solutions = []
# Check n from 0 to 20
for n in range(21):
    E_n = calculate_E(n)
    if E_n is not None:
        solutions.append(n)

print(f"Solutions found for n=0 to 20: {solutions}")

# Specific verification for n=6
E_6 = calculate_E(6)
if E_6 is None:
    print(f"Verification for n=6: Not an integer solution.")
else:
    print(f"Verification for n=6: Integer solution found: {E_6}")

